'use strict';
let featherPreview=null,featherGeneration=0;
const overlapSurfaces=[document.createElement('canvas'),document.createElement('canvas')];
document.querySelector('.rig-workspace aside').insertAdjacentHTML('beforeend','<details id="rigFeatherTools"><summary>Edge feathering & overlap</summary><label>Feather radius (px)<input id="rigFeatherRadius" type="range" min="0" max="20" value="0"></label><img id="rigFeatherPreview" alt="Selected cut-out feather preview" hidden><div class="rig-tools"><button id="previewRigFeather">Preview edges</button><button id="applyRigFeather">Apply feathering</button><button id="resetRigFeather">Reset feathering</button></div><label><input id="rigShowOverlap" type="checkbox"> Highlight overlap with parent</label><p class="note">Feathering softens the cut-out alpha edge without blurring its colours. Magenta marks where the selected part overlaps its parent. Prepare overlapping artwork to cover moving joints.</p></details>');
async function featherRigImage(src,radius){const image=await imageReady(src),canvas=document.createElement('canvas'),mask=document.createElement('canvas');canvas.width=mask.width=image.naturalWidth;canvas.height=mask.height=image.naturalHeight;const g=canvas.getContext('2d'),m=mask.getContext('2d');g.drawImage(image,0,0);if(radius>0){m.filter='blur('+radius+'px)';m.drawImage(image,0,0);g.globalCompositeOperation='destination-in';g.drawImage(mask,0,0)}return canvas.toDataURL('image/png')}
async function previewRigFeather(){const part=currentRigPart();if(!part)return toast('Select a cut-out part first.');const generation=++featherGeneration,src=part.edgeFeatherOriginal||part.src,radius=+$('rigFeatherRadius').value,result=await featherRigImage(src,radius);if(generation!==featherGeneration||part!==currentRigPart())return;featherPreview={part,src:result,original:src,radius};$('rigFeatherPreview').src=result;$('rigFeatherPreview').hidden=false;return featherPreview}
$('previewRigFeather').onclick=()=>previewRigFeather().catch(e=>toast(e.message));$('rigFeatherRadius').onchange=()=>previewRigFeather().catch(e=>toast(e.message));$('applyRigFeather').onclick=async()=>{try{const preview=await previewRigFeather();if(!preview)return;preview.part.edgeFeatherOriginal=preview.original;preview.part.edgeFeatherRadius=preview.radius;preview.part.src=preview.src;await imageReady(preview.src);paintRigEditor();toast('Softened edges applied to this draft part.')}catch(e){toast(e.message)}};$('resetRigFeather').onclick=async()=>{const part=currentRigPart();if(!part?.edgeFeatherOriginal)return;part.src=part.edgeFeatherOriginal;delete part.edgeFeatherOriginal;delete part.edgeFeatherRadius;await imageReady(part.src);renderRigParts();paintRigEditor()};$('rigShowOverlap').onchange=paintRigEditor;
const renderPartsBeforeFeather=renderRigParts;renderRigParts=function(){renderPartsBeforeFeather();featherGeneration++;featherPreview=null;$('rigFeatherPreview').hidden=true;$('rigFeatherRadius').value=currentRigPart()?.edgeFeatherRadius||0;for(const id of ['previewRigFeather','applyRigFeather','resetRigFeather','rigFeatherRadius'])$(id).disabled=!currentRigPart()};
const maskCommitBeforeFeather=commitRigMask;commitRigMask=async function(info){if(info.target!==imageRigDraft){delete info.target.edgeFeatherOriginal;delete info.target.edgeFeatherRadius}return maskCommitBeforeFeather(info)};
const paintBeforeOverlap=paintRigEditor;paintRigEditor=function(){paintBeforeOverlap();if(!$('rigShowOverlap').checked||!imageRigDraft)return;const d=imageRigDraft,part=currentRigPart(),parent=d.parts.find(p=>p.id===part?.parentId);if(!part||!parent)return;const [a,b]=overlapSurfaces;for(const c of [a,b]){c.width=d.imageWidth;c.height=d.imageHeight}const x=a.getContext('2d'),y=b.getContext('2d'),own=loadImage(part.src),other=loadImage(parent.src);if(!own.complete||!other.complete)return;x.drawImage(own,part.x,part.y,part.width,part.height);y.drawImage(other,parent.x,parent.y,parent.width,parent.height);x.globalCompositeOperation='destination-in';x.drawImage(b,0,0);x.globalCompositeOperation='source-in';x.fillStyle='#fa4bd6';x.fillRect(0,0,a.width,a.height);rigContext.save();rigContext.globalAlpha=.7;rigContext.drawImage(a,0,0);rigContext.restore()};
const validateBeforeFeather=valid;valid=function(p){const check=part=>(part.edgeFeatherRadius===undefined||Number.isFinite(part.edgeFeatherRadius)&&part.edgeFeatherRadius>=0&&part.edgeFeatherRadius<=20)&&(part.edgeFeatherOriginal===undefined||typeof part.edgeFeatherOriginal==='string'&&part.edgeFeatherOriginal.startsWith('data:image/png;base64,')&&part.edgeFeatherOriginal.length<12e6);return validateBeforeFeather(p)&&p.scenes.every(s=>s.objects.every(o=>o.type!=='puppet'||o.parts.every(check)&&Object.values(o.characterViews||{}).every(art=>art.parts.every(check))))};
